explicit WallBoundary(const std::string &shape_name) : ComplexShape(shape_name)
    {
        add<GeometricShapeBox>(Transform(outer_wall_translation), outer_wall_halfsize);
        subtract<GeometricShapeBox>(Transform(inner_wall_translation), inner_wall_halfsize);
    }

int main(int ac, char *av[])
{
    //----------------------------------------------------------------------
    //	Build up an SPHSystem and IO environment.
    //----------------------------------------------------------------------
    BoundingBoxd system_domain_bounds(Vec2d(-BW, -BW), Vec2d(DL + BW, DH + BW));
    SPHSystem sph_system(system_domain_bounds, particle_spacing_ref);
    sph_system.handleCommandlineOptions(ac, av);
    //----------------------------------------------------------------------
    //	Creating bodies with corresponding materials and particles.
    //----------------------------------------------------------------------
    GeometricShapeBox initial_water_block(Transform(water_block_translation), water_block_halfsize, "WaterBody");
    FluidBody water_block(sph_system, initial_water_block);
    water_block.defineMatterMaterial<WeaklyCompressibleFluid>(rho0_f, c_f);
    water_block.generateParticles<BaseParticles, Lattice>();

    SolidBody wall_boundary(sph_system, makeShared<WallBoundary>("WallBoundary"));
    wall_boundary.defineMatterMaterial<Solid>();
    wall_boundary.generateParticles<BaseParticles, Lattice>();

    ObserverBody fluid_observer(sph_system, "FluidObserver");
    StdVec<Vecd> observation_location = {Vecd(DL, 0.2)};
    fluid_observer.generateParticles<ObserverParticles>(observation_location);
    //----------------------------------------------------------------------
    //	Define body relation map.
    //	The contact map gives the topological connections between the bodies.
    //	Basically the the range of bodies to build neighbor particle lists.
    //  Generally, we first define all the inner relations, then the contact relations.
    //----------------------------------------------------------------------
    InnerRelation water_block_inner(water_block);
    ContactRelation water_wall_contact(water_block, {&wall_boundary});
    ContactRelation fluid_observer_contact(fluid_observer, {&water_block});
    //----------------------------------------------------------------------
    // Combined relations built from basic relations
    // which is only used for update configuration.
    //----------------------------------------------------------------------
    ComplexRelation water_wall_complex(water_block_inner, water_wall_contact);
    //----------------------------------------------------------------------
    // Define the numerical methods used in the simulation.
    // Note that there may be data dependence on the sequence of constructions.
    // Generally, the geometric models or simple objects without data dependencies,
    // such as gravity, should be initiated first.
    // Then the major physical particle dynamics model should be introduced.
    // Finally, the auxiliary models such as time step estimator, initial condition,
    // boundary condition and other constraints should be defined.
    //----------------------------------------------------------------------
    Gravity gravity(Vecd(0.0, -gravity_g));
    SimpleDynamics<GravityForce<Gravity>> constant_gravity(water_block, gravity);
    SimpleDynamics<NormalDirectionFromBodyShape> wall_boundary_normal_direction(wall_boundary);

Dynamics1Level<fluid_dynamics::Integration1stHalfWithWallRiemann> fluid_pressure_relaxation(water_block_inner, water_wall_contact);
Dynamics1Level<fluid_dynamics::Integration2ndHalfWithWallRiemann> fluid_density_relaxation(water_block_inner, water_wall_contact);
InteractionWithUpdate<fluid_dynamics::DensitySummationComplexFreeSurface> fluid_density_by_summation(water_block_inner, water_wall_contact);

ReduceDynamics<fluid_dynamics::AdvectionTimeStep> fluid_advection_time_step(water_block, U_ref);
ReduceDynamics<fluid_dynamics::AcousticTimeStep> fluid_acoustic_time_step(water_block);
//----------------------------------------------------------------------
//	Define the configuration related particles dynamics.
//----------------------------------------------------------------------
ParticleSorting particle_sorting(water_block);
//----------------------------------------------------------------------
//	Define the methods for I/O operations, observations
//	and regression tests of the simulation.
//----------------------------------------------------------------------
BodyStatesRecordingToVtp body_states_recording(sph_system);
body_states_recording.addToWrite<Vecd>(wall_boundary, "NormalDirection");
RestartIO restart_io(sph_system);
RegressionTestDynamicTimeWarping<ReducedQuantityRecording<TotalMechanicalEnergy>> write_water_mechanical_energy(water_block, gravity);
RegressionTestDynamicTimeWarping<ObservedQuantityRecording<Real>> write_recorded_water_pressure("Pressure", fluid_observer_contact);
//----------------------------------------------------------------------
//	Prepare the simulation with cell linked list, configuration
//	and case specified initial condition if necessary.
//----------------------------------------------------------------------
sph_system.initializeSystemCellLinkedLists();
sph_system.initializeSystemConfigurations();
wall_boundary_normal_direction.exec();
constant_gravity.exec();
//----------------------------------------------------------------------
//	Load restart file if necessary.
//----------------------------------------------------------------------
Real &physical_time = *sph_system.getSystemVariableDataByName<Real>("PhysicalTime");
if (sph_system.RestartStep() != 0)
{
    restart_io.readRestartFiles(sph_system.RestartStep());
    water_block.updateCellLinkedList();
    water_wall_complex.updateConfiguration();
    fluid_observer_contact.updateConfiguration();
}
//----------------------------------------------------------------------
//	Setup for time-stepping control
//----------------------------------------------------------------------
size_t number_of_iterations = sph_system.RestartStep();
int screen_output_interval = 100;
int observation_sample_interval = screen_output_interval * 2;
int restart_output_interval = screen_output_interval * 10;
Real end_time = 20.0;
Real output_interval = 0.1;
//----------------------------------------------------------------------
//	Statistics for CPU time
//----------------------------------------------------------------------

TickCount t1 = TickCount::now();
TimeInterval interval;
TimeInterval interval_computing_time_step;
TimeInterval interval_computing_fluid_pressure_relaxation;
TimeInterval interval_updating_configuration;
TickCount time_instance;
//----------------------------------------------------------------------
//	First output before the main loop.
//----------------------------------------------------------------------
body_states_recording.writeToFile();
write_water_mechanical_energy.writeToFile(number_of_iterations);
write_recorded_water_pressure.writeToFile(number_of_iterations);
//----------------------------------------------------------------------
//	Main loop starts here.
//----------------------------------------------------------------------
while (physical_time < end_time)
{
    Real integration_time = 0.0;
    /** Integrate time (loop) until the next output time. */
    while (integration_time < output_interval)
    {
        /** outer loop for dual-time criteria time-stepping. */
        time_instance = TickCount::now();
        Real advection_dt = fluid_advection_time_step.exec();
        fluid_density_by_summation.exec();
        interval_computing_time_step += TickCount::now() - time_instance;

        time_instance = TickCount::now();
        Real relaxation_time = 0.0;
        Real acoustic_dt = 0.0;
        while (relaxation_time < advection_dt)
        {
            /** inner loop for dual-time criteria time-stepping.  */
            acoustic_dt = fluid_acoustic_time_step.exec();
            fluid_pressure_relaxation.exec(acoustic_dt);
            fluid_density_relaxation.exec(acoustic_dt);
            relaxation_time += acoustic_dt;
            integration_time += acoustic_dt;
            physical_time += acoustic_dt;
        }
        interval_computing_fluid_pressure_relaxation += TickCount::now() - time_instance;

        /** screen output, write body observables and restart files  */
        if (number_of_iterations % screen_output_interval == 0)
        {
            std::cout << std::fixed << std::setprecision(9) << "N=" << number_of_iterations << "	Time = "
                      << physical_time
                      << "	advection_dt = " << advection_dt << "	acoustic_dt = " << acoustic_dt << "\n";

            if (number_of_iterations % observation_sample_interval == 0 && number_of_iterations != sph_system.RestartStep())

            {
                write_water_mechanical_energy.writeToFile(number_of_iterations);
                write_recorded_water_pressure.writeToFile(number_of_iterations);
            }
            if (number_of_iterations % restart_output_interval == 0)
                restart_io.writeToFile(number_of_iterations);
        }
        number_of_iterations++;

        /** Update cell linked list and configuration. */
        time_instance = TickCount::now();
        if (number_of_iterations % 100 == 0 && number_of_iterations != 1)
        {
            particle_sorting.exec();
        }
        water_block.updateCellLinkedList();
        water_wall_complex.updateConfiguration();
        fluid_observer_contact.updateConfiguration();
        interval_updating_configuration += TickCount::now() - time_instance;
    }

    body_states_recording.writeToFile();
    TickCount t2 = TickCount::now();
    TickCount t3 = TickCount::now();
    interval += t3 - t2;
}
TickCount t4 = TickCount::now();

TimeInterval tt;
tt = t4 - t1 - interval;
std::cout << "Total wall time for computation: " << tt.seconds()
          << " seconds." << std::endl;
std::cout << std::fixed << std::setprecision(9) << "interval_computing_time_step ="
          << interval_computing_time_step.seconds() << "\n";
std::cout << std::fixed << std::setprecision(9) << "interval_computing_fluid_pressure_relaxation = "
          << interval_computing_fluid_pressure_relaxation.seconds() << "\n";
std::cout << std::fixed << std::setprecision(9) << "interval_updating_configuration = "
          << interval_updating_configuration.seconds() << "\n";

if (sph_system.GenerateRegressionData())
{
    write_water_mechanical_energy.generateDataBase(1.0e-3);
    write_recorded_water_pressure.generateDataBase(1.0e-3);
}
else if (sph_system.RestartStep() == 0)
{
    write_water_mechanical_energy.testResult();
    write_recorded_water_pressure.testResult();
}

Real getLeftStateInWeno(Real v_1, Real v_2, Real v_3, Real v_4)
{
    Real v1 = v_1;
    Real v2 = v_2;
    Real v3 = v_3;
    Real v4 = v_4;

    Real f1 = 0.5 * v2 + 0.5 * v3;
    Real f2 = (-0.5) * v1 + 1.5 * v2;
    Real f3 = v2 / 3.0 + 5.0 * v3 / 6.0 - v4 / 6.0;

    Real epsilon = 1.0e-6;
    Real s1 = pow(v2 - v3, 2) + epsilon;
    Real s2 = pow(v2 - v1, 2) + epsilon;
    Real s3 = pow(3.0 * v2 - 4.0 * v3 + v4, 2) / 4.0 + 13.0 * pow(v2 - 2.0 * v3 + v4, 2) / 12.0 + epsilon;
    Real s12 = 13.0 * pow(v1 - 2.0 * v2 + v3, 2) / 12.0 + pow(v1 - v3, 2) / 4.0 + epsilon;
    Real tau_4 = (v1 * (547.0 * v1 - 2522.0 * v2 + 1922.0 * v3 - 494.0 * v4) + v2 * (3443.0 * v2 - 5966.0 * v3 + 1602.0 * v4) + v3 * (2843.0 * v3 - 1642.0 * v4) + 267.0 * v4 * v4) / 240.0;

    Real alpha_1 = (1.0 + (tau_4 / s1) * (tau_4 / s12)) / 3.0;
    Real alpha_2 = (1.0 + (tau_4 / s2) * (tau_4 / s12)) / 6.0;
    Real alpha_3 = (1.0 + tau_4 / s3) / 2.0;
    Real w_1 = alpha_1 / (alpha_1 + alpha_2 + alpha_3);
    Real w_2 = alpha_2 / (alpha_1 + alpha_2 + alpha_3);
    Real w_3 = alpha_3 / (alpha_1 + alpha_2 + alpha_3);
    Real left_state = w_1 * f1 + w_2 * f2 + w_3 * f3;

    return left_state;
}

Real getRightStateInWeno(Real v_1, Real v_2, Real v_3, Real v_4)
{
    Real v1 = v_4;
    Real v2 = v_3;
    Real v3 = v_2;
    Real v4 = v_1;

    Real f1 = 0.5 * v2 + 0.5 * v3;
    Real f2 = (-0.5) * v1 + 1.5 * v2;
    Real f3 = v2 / 3.0 + 5.0 * v3 / 6.0 - v4 / 6.0;

    Real epsilon = 1.0e-6;
    Real s1 = pow(v2 - v3, 2) + epsilon;
    Real s2 = pow(v2 - v1, 2) + epsilon;
    Real s3 = pow(3.0 * v2 - 4.0 * v3 + v4, 2) / 4.0 + 13.0 * pow(v2 - 2.0 * v3 + v4, 2) / 12.0 + epsilon;
    Real s12 = 13.0 * pow(v1 - 2.0 * v2 + v3, 2) / 12.0 + pow(v1 - v3, 2) / 4.0 + epsilon;
    Real tau_4 = (v1 * (547.0 * v1 - 2522.0 * v2 + 1922.0 * v3 - 494.0 * v4) + v2 * (3443.0 * v2 - 5966.0 * v3 + 1602.0 * v4) + v3 * (2843.0 * v3 - 1642.0 * v4) + 267.0 * v4 * v4) / 240.0;

    Real alpha_1 = (1.0 + (tau_4 / s1) * (tau_4 / s12)) / 3.0;
    Real alpha_2 = (1.0 + (tau_4 / s2) * (tau_4 / s12)) / 6.0;
    Real alpha_3 = (1.0 + tau_4 / s3) / 2.0;
    Real w_1 = alpha_1 / (alpha_1 + alpha_2 + alpha_3);
    Real w_2 = alpha_2 / (alpha_1 + alpha_2 + alpha_3);
    Real w_3 = alpha_3 / (alpha_1 + alpha_2 + alpha_3);
    Real right_state = w_1 * f1 + w_2 * f2 + w_3 * f3;

    return right_state;
}

DataType &operator[](UnsignedInt index) const
    {
        return *(data_ + entry_ + index * width_);
    }

DataType *operator[](UnsignedInt index) const
    {
        return data_ + index * width_;
    }

SingleVariable(const std::string &name, Args &&...args)
        : Quantity(name), data_(new DataType(std::forward<Args>(args)...)),
          delegated_(data_){}

DiscreteVariable(const std::string &name, UnsignedInt size,
                     const InitializationFunction &initialization)
        : Quantity(name), size_(size), width_(1), data_(new DataType[size]),
          device_only_variable_(nullptr)
    {
        fill(initialization, 0, size);
    }

DiscreteVariable(const std::string &name, UnsignedInt size,
                     const MultiEntryTag &tag, UnsignedInt width)
        : Quantity(name), size_(size), width_(width), data_(new DataType[size * width]),
          device_only_variable_(nullptr)
    {
        for (UnsignedInt i = 0; i < width; i++)
        {
            entry_names_.push_back(std::to_string(i));
            fill([&](UnsignedInt index) // zero initialization
                 { return ZeroData<DataType>::value; }, 0, size, i);
        }
    }

DiscreteVariable(const std::string &name, UnsignedInt size, StdVec<std::string> entry_names)
        : DiscreteVariable(name, size, MultiEntryTag{}, entry_names.size())
    {
        entry_names_ = entry_names;
    }

UnsignedInt getEntryIndexByName(std::string entry_name)
    {
        auto iter = std::find(entry_names_.begin(), entry_names_.end(), entry_name);
        if (iter != entry_names_.end())
        {
            return std::distance(entry_names_.begin(), iter);
        }
        else
        {
            std::cout << "\n Error: the variable '" << this->name_
                      << "' does not have a entry named '" << entry_name << "'!" << std::endl;
            exit(1);
        }
    }

DataType getEntryValueWithScalingRef(UnsignedInt index, UnsignedInt entry) const
    {
        return data_[index * width_ + entry] * scaling_ref_;
    }

void fill(const FillFunction &fill_function, UnsignedInt begin_index,
              UnsignedInt fill_size, UnsignedInt entry = 0)
    {
        if (begin_index + fill_size > size_)
        {
            std::cout << "\n Error: trying to fill data out of range in DiscreteVariable '"
                      << this->name_ << "'!" << std::endl;
            exit(1);
        }

        for (UnsignedInt i = begin_index; i < begin_index + fill_size; ++i)
        {
            data_[i * width_ + entry] = fill_function(i);
        }
    }

DataView<DataType> DelegatedDataView(const ExecutionPolicy &ex_policy)
    {
        if (width_ != 1)
        {
            std::cout << "\n Error: the variable '" << this->name_
                      << "' is not a single entry variable!" << std::endl;
            exit(1);
        }

        return DataView<DataType>(DelegatedData(ex_policy));
    }

EntryView<DataType> DelegatedEntryView(const ExecutionPolicy &ex_policy, UnsignedInt entry)
    {
        if (entry >= width_)
        {
            std::cout << "\n Error: entry index out of range in variable '"
                      << this->name_ << "'!" << std::endl;
            exit(1);
        }

        return EntryView<DataType>(DelegatedData(ex_policy), entry, width_);
    }

EntryView<DataType> DelegatedEntryView(const ExecutionPolicy &ex_policy, std::string entry_name)
    {
        return DelegatedEntryView(ex_policy, getEntryIndexByName(entry_name));
    }

void reallocateData(const ExecutionPolicy &ex_policy, UnsignedInt tentative_size)
    {
        if (size_ < tentative_size)
        {
            reallocateData(tentative_size);
        }
    }

void reallocateData(const ParallelDevicePolicy &par_device, UnsignedInt tentative_size)
    {
        if (size_ < tentative_size)
        {
            reallocateDataOnDevice(tentative_size);
        }
    }

void reallocateData(UnsignedInt tentative_size)
    {
        delete[] data_;
        size_ = tentative_size + tentative_size / 4;
        data_ = new DataType[size_ * width_];
    }

TEST(test_scalar_functions, test_WENO)
{
    Real v1 = 1.0;
    Real v2 = 2.0;
    Real v3 = 3.0;
    Real v4 = 4.0;

    Real Left_state = getLeftStateInWeno(v1, v2, v3, v4);
    Real Right_state = getRightStateInWeno(v4, v3, v2, v1);
    EXPECT_EQ(2.5, Left_state);
    EXPECT_EQ(2.5, Right_state);
}

int main(int argc, char *argv[])
{
    testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}
